class Solution:
    def mergeKLists(self, lists: List[ListNode]) -> ListNode:
        def mergeTwoList(l1, l2):
            if not l1:
                return l2
            if not l2:
                return l1
            if l1.val < l2.val:
                l1.next = mergeTwoList(l1.next, l2)
                return l1
            else:
                l2.next = mergeTwoList(l1, l2.next)
                return l2
        n = len(lists)
        for i in range(1, n):
            lists[i] = mergeTwoList(lists[i - 1], lists[i])
        return lists[-1]
